/* @autogenerated */
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { of, throwError } from 'rxjs';
import { EntityDocumentComponent } from './entity-document.component';
import { DocumentService, TemplateNotFoundError } from './document.service';

describe('EntityDocumentComponent', () => {
  let fixture: ComponentFixture<EntityDocumentComponent>;
  let component: EntityDocumentComponent;
  let documents: jasmine.SpyObj<DocumentService>;
  const definition = { template: 'x/report', fileName: (item: any) => 'report-' + item.uid } as any;

  const settle = async () => {
    for (let i = 0; i < 50 && component.status() === 'loading'; i++) {
      await new Promise((resolve) => setTimeout(resolve));
    }
  };

  const create = (item: any = { uid: '1' }, extra: any = {}) => {
    fixture = TestBed.createComponent(EntityDocumentComponent);
    fixture.componentRef.setInput('definition', { ...definition, ...extra });
    fixture.componentRef.setInput('item', item);
    component = fixture.componentInstance;
    fixture.detectChanges();
  };

  beforeEach(() => {
    documents = jasmine.createSpyObj<DocumentService>('DocumentService', ['markdown', 'html', 'download']);
    documents.markdown.and.returnValue(of('# Report'));
    documents.html.and.resolveTo('<h1>Report</h1>');
    documents.download.and.resolveTo();
    TestBed.configureTestingModule({
      imports: [EntityDocumentComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
      providers: [{ provide: DocumentService, useValue: documents }],
    });
    TestBed.overrideTemplate(EntityDocumentComponent, '');
  });

  afterEach(() => TestBed.resetTestingModule());

  it('renders the preview of the item document', async () => {
    create();
    await settle();

    expect(documents.markdown).toHaveBeenCalledWith(jasmine.objectContaining({ template: 'x/report' }), { uid: '1' });
    expect(component.preview()).toBe('<h1>Report</h1>');
    expect(component.status()).toBe('ready');
    expect(component.formats()).toEqual(['docx', 'pdf']);
  });

  it('waits for the item', () => {
    fixture = TestBed.createComponent(EntityDocumentComponent);
    fixture.componentRef.setInput('definition', definition);
    component = fixture.componentInstance;
    fixture.detectChanges();

    expect(documents.markdown).not.toHaveBeenCalled();
    expect(component.status()).toBe('loading');
  });

  it('offers the formats of the definition', () => {
    create({ uid: '1' }, { formats: ['pdf'] });

    expect(component.formats()).toEqual(['pdf']);
  });

  it('says when there is no template', async () => {
    documents.markdown.and.returnValue(throwError(() => new TemplateNotFoundError('x/report')));
    create();
    await settle();

    expect(component.status()).toBe('failed');
    expect(component.error()).toBe('notFound');
  });

  it('says when the template can not be filled', async () => {
    documents.markdown.and.returnValue(throwError(() => new Error('bad')));
    create();
    await settle();

    expect(component.error()).toBe('render');
  });

  it('downloads the document in a format with its file name', async () => {
    create();
    await settle();

    const done = component.download('pdf');
    expect(component.generating()).toBe('pdf');
    await done;

    expect(documents.download).toHaveBeenCalledWith('# Report', 'pdf', 'report-1');
    expect(component.generating()).toBeUndefined();
  });

  it('fails when the file can not be generated', async () => {
    documents.download.and.rejectWith(new Error('pdf'));
    create();
    await settle();

    await component.download('docx');

    expect(component.status()).toBe('failed');
    expect(component.error()).toBe('file');
  });
});
